while True:
 h={}
 while True:
  line=sys.stdin.buffer.readline()
  if not line: sys.exit(0)
  if line in (b'\r\n',b'\n'): break
  key,value=line.decode().split(':',1);h[key.lower()]=value.strip()
 req=json.loads(sys.stdin.buffer.read(int(h['content-length'])))
 command=req['command']
 body={'seq':1,'type':'response','request_seq':req['seq'],'command':command,'success':command=='initialize','message':'launch rejected','body':{'supportsConfigurationDoneRequest':True}}
 payload=json.dumps(body).encode();sys.stdout.buffer.write(f'Content-Length: {len(payload)}\r\n\r\n'.encode()+payload);sys.stdout.buffer.flush()
